import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine().trim());
        String s = scanner.nextLine().trim();

        int[] x = new int[n + 1];
        int[] y = new int[n + 1];
        x[0] = 0;
        y[0] = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int dx = 0, dy = 0;
            if (c == 'U') dy = 1;
            else if (c == 'D') dy = -1;
            else if (c == 'R') dx = 1;
            else if (c == 'L') dx = -1;
            x[i + 1] = x[i] + dx;
            y[i + 1] = y[i] + dy;
        }

        long count = 0;
        for (int i = 0; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                if (x[i] == x[j] && y[i] == y[j]) {
                    count++;
                }
            }
        }

        System.out.println(count);
    }
}
